quests[24226] = { id = 24226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, {class}, go to Arathi Basin and crush the enemy.  Victory to the Horde!", sourceObjective = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[24426] = { id = 24426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, {name}.  Earn great honor by heeding the call of the brave Frostwolf warriors.", sourceObjective = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran or Shattrath.", completion = "There is no greater honor than driving invaders from Horde territories.  We salute your great courage in aiding our forces today!", sourceObjectiveStatus = "unverified-source-field" }
quests[24427] = { id = 24427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, {name}, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!", sourceObjective = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran or Shattrath.", completion = "Just what I wanted to hear!  A victory in Alterac Valley - even a temporary one - is crucial to our overall strategy against the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[24428] = { id = 24428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Puzzling Circumstance", description = "You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Zardeth of the Black Claw.", sourceObjective = "Take the Head of Onyxia to Zardeth of the Black Claw in the basement of the Slaughtered Lamb.", progress = "By Nozdormu's teeth!", completion = "What? How did you get this? Isn't she... Never mind the details, I suppose. You'll be wanting one of these baubles as recompense, no doubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24429] = { id = 24429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Most Puzzling Circumstance", description = "You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Neeru Fireblade.", sourceObjective = "Take the Head of Onyxia to Neeru Fireblade in the Cleft of Shadow.", progress = "What is the meaning of this?!", completion = "You've brought me the head of someone who is... No, best not to think about it too hard. You'll be wanting recompense for your heroic deeds, no doubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24431] = { id = 24431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waterlogged Recipe", description = "This appears to be the remains of a mixture for potent wine.  Perhaps the proprietor of One More Glass in Dalaran would be interested in it....", sourceObjective = "Bring the Waterlogged Recipe to Christi Stockton in the Dalaran city.", progress = "Wine is only as fine as the person drinking it, I always say.", completion = "This is quite a find, {name}.  I can't have you selling this to anyone else, so I'm willing to offer generously.", sourceObjectiveStatus = "unverified-source-field" }
quests[24442] = { id = 24442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Plans Of The Kvaldir", description = "Looking over the captured attack plans, you find a map of the Eastern Kingdoms and Kalimdor with major settlements marked. Reading over the orders, you learn that  Kvaldir captains have drafted plans for a series of devastating raids.\n\nAccording to the orders, the attacks are to begin after Mistcaller Yngvar \"consults the Heart of the Mists.\" Perhaps you could delay the attacks by capturing the omen from the Mistcaller's Cave on the western side of Hrothgar's Landing and notify Justicar Mariel Trueheart.", sourceObjective = "Recover the Heart of the Mists and bring it and the Kvaldir Attack Plans to Justicar Mariel Trueheart at the Argent Tournament Grounds.", progress = "What is it that you've found, {name}?", completion = "<Mariel accepts the orders and the captured seeing crystal and examines both.>\n\nGood work, {name}, and quick thinking. I'm sure the theft of this trinket won't slow them down for long, but I think you've bought us time to warn the leaders of the Horde and Alliance about the impending attacks.", sourceObjectiveStatus = "unverified-source-field" }
quests[24451] = { id = 24451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience With The Arcanist", description = "I've placed an enchantment on the tabard that should allow you to slip past the Silver Enclave's defenses for a short period of time. You should have enough time to find your way up to the top level of the Silver Enclave and meet up with the Silver Covenant's man there, known as Arcanist Tybalin.\n\nWhile disguised, obtain the copy of Ancient Dragonforged Blades that his men borrowed from Wyrmrest, and return the book to me.", sourceObjective = "Retrieve the Ancient Dragonforged Blades tome from Arcanist Tybalin.", progress = "Did you recover the book from Wyrmrest?", completion = "Excellent work. Now that this is in our hands, we must get it to Myralion Sunblaze as soon as possible. We can't risk the Silver Covenant taking the book from us again.\n\nI'll get that tabard back to Shandy and see that he's well compensated for his assistance. Once the book is in Myralion's hands, the Silver Covenant won't be a threat anymore.", sourceObjectiveStatus = "unverified-source-field" }
quests[24454] = { id = 24454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return To Caladis Brightspear", description = "We must get this book to Caladis Brightspear immediately. Would you bring it to him? I cannot rely on anyone else to transport the book and you have proven adept at keeping the Sunreavers at bay.\n\nTake it with you to Quel'Delar's rest, south of the Argent Tournament Grounds in Icecrown. Caladis and the sword will be waiting. The sooner we can identify the blade, the sooner we can claim it.", sourceObjective = "Bring Ancient Dragonforged Blades to Caladis Brightspear at Quel'Delar's Rest.", progress = "We've been expecting your return. What has kept you?", completion = "<Caladis accepts the heavy book and begins leafing through it.>\n\nI knew the symbols on the blade were familiar. The weapon was most certainly forged by the dragons and gifted to one of the mortal races, but which blade is this, and how did it come to rest in Icecrown?", sourceObjectiveStatus = "unverified-source-field" }
quests[24461] = { id = 24461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reforging The Sword", description = "We cannot allow Quel'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel.\n\nIn the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel'Delar.\n\nYou must gather bars of infused saronite and capture the forgemaster's hammer, then bring them to the forgemaster's anvil and reforge the sword.", sourceObjective = "Obtain 5 Infused Saronite Bars and the Forgemaster's Hammer and use them to make the Reforged Quel'Delar.", progress = "Were you able to reconstruct Quel'Delar?", completion = "You have remade the blade of Quel'Delar, although Blood-Queen Lana'thel proclaimed we could not! The blade must still be tempered, but she and her master will not stand in our way!", sourceObjectiveStatus = "unverified-source-field" }
quests[24476] = { id = 24476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempering The Blade", description = "At last, the pieces of Quel'Delar are rejoined and the blade is whole, but it cannot see battle until you have tempered it. That jagged saronite edge is brittle and will shatter the moment it strikes anything.\n\nDeep in Icecrown Citadel's Forge of Souls is a place where the blade can safely be tempered. Take Quel'Delar with you to the abode of the Devourer of Souls and look for the crucible. Plunge the blade into the crucible to temper it and bring it back to me in The Frozen Halls.", sourceObjective = "Temper the Reforged Quel'Delar in the Crucible of Souls.", progress = "Until the sword is tempered, it will be useless.", completion = "I... I don't understand. Tempering the sword should've restored the blade to its original condition. What has happened here?", sourceObjectiveStatus = "unverified-source-field" }
quests[24480] = { id = 24480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Halls Of Reflection", description = "You have reforged and tempered the sword, yet it sits quietly in its sheath, showing no signs of the power it should possess. You say the sword pulls you, as though it possesses a will?\n\nDare you bring it where it wishes to go? It's not right that the sword should be this silent and this insistent, yet I fear that if you do not take the sword to its destination, we will never learn why. Take it into Icecrown Citadel's Halls of Reflection, but be on your guard! I'll be waiting for you in The Frozen Halls.", sourceObjective = "Bring your Tempered Quel'Delar to Sword's Rest inside the Halls of Reflection.", progress = "What happened inside the Halls of Reflection?", completion = "I had not thought it possible for evil to take hold in such a sword, but I suppose it was naive of me. If the greatest of dragonkind's creations could be corrupted and turned against them, why not a mere sword?\n\nUther's advice is wise, {name}, and I would urge you to heed it quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[24498] = { id = 24498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to the Citadel", description = "They've put our captured soldiers to work in the quarry! Kill their captors and set them free, hero, and do it quickly. We will need their aid when we confront Scourgelord Tyrannus.", sourceObjective = "Free 15 Alliance Slaves and kill Forgemaster Garfrost.", progress = "My men and I appreciate your help, {class}. More than we could possibly express in these trying times.", completion = "You've done well this day. With many of the slaves freed and now with access to the forges, it will not be long before I have a strong force to aid in delivering us from Scourgelord Tyrannus and this foul pit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24499] = { id = 24499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Tortured Souls", description = "I cannot thank you enough for coming. We're severely undermanned to be risking a venture into the citadel, but opportunities like this are too rare to pass up.\n\nI'm awaiting the arrival of champions from the coliseum, but if your reputation holds true, you should be more than equipped to fight through the forge yourself. Clear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the citadel.\n\nPlease hurry, {name}. We're counting on you.", sourceObjective = "Kill Bronjahm and the Devourer of Souls to secure access to the Pit of Saron.", completion = "Just in time! Thank you, {name}.\n\nThe Pit of Saron lies ahead, and if our scouts are correct, past that will be the Halls of Reflection. It is there that Arthas lets his guard down, and it is there that we hope to find a clue to his weakness... or maybe, just maybe, his redemption.", sourceObjectiveStatus = "unverified-source-field" }
quests[24500] = { id = 24500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King", description = "Uther knew a great deal about how Arthas might be defeated. It's hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that?\n\nMany questions remain, but the answers that you've uncovered may be critical to ensuring Arthas' defeat. You need to find Jaina and escape the Lich King while there's still time.", sourceObjective = "Find Lady Jaina Proudmoore and escape the Halls of Reflection", completion = "<Jaina is still catching her breath.>\n\nI can barely believe we're still alive. It was foolish of me to follow him. I've made that mistake too many times.  And you... it was reckless of you to come after me instead of escaping with the information! But... well... thank you. You truly are a hero.\n\nWith Uther's guidance, we may stand a chance at defeating Arthas. All the lives lost today were not in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[24506] = { id = 24506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inside the Frozen Citadel", description = "{class}! Come close quickly, I must have a word!\n\nMy queen, the Lady Sylvanas Windrunner, has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as \"The Forge of Souls.\" She sent word before she left for me to find fierce fighters to send her way. I think you'll do.\n\nGo to her within the entrance to the forge, {class}.", sourceObjective = "Enter The Forge of Souls from the side of Icecrown Citadel and locate Lady Sylvanas Windrunner.", completion = "Good. {name}, I know of you. You'll be perfect for these tasks.\n\nWe've been afforded a rare chance to delve into Icecrown Citadel, but we must move quickly if we're to avoid Arthas' notice.", sourceObjectiveStatus = "unverified-source-field" }
quests[24507] = { id = 24507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to the Citadel", description = "They've put our captured soldiers to work in the quarry. Kill their captors and set them free, {class}, and do it quickly. We will need their aid when we confront Scourgelord Tyrannus.", sourceObjective = "Free 15 Horde Slaves and kill Forgemaster Garfrost.", progress = "Thank you, {class}. You will have our blood and our steel behind you this day.", completion = "You've done well this day. With many of the slaves freed and now with access to the forges, it will not be long before I have a strong force to aid in delivering us from Scourgelord Tyrannus and this foul pit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24508] = { id = 24508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temp Quest Record" }
quests[24509] = { id = 24509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temp Quest Record" }
quests[24510] = { id = 24510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inside the Frozen Citadel", description = "{class}! Come close quickly, I must have a word!\n\nMy patron, the Lady Jaina Proudmoore, has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as \"The Forge of Souls.\" She sent word before she left for me to find any help that I could... and, well, I was hoping that might be you.\n\nPlease, find her there as soon as you can.", sourceObjective = "Enter The Forge of Souls from the side of Icecrown Citadel and find Lady Jaina Proudmoore.", completion = "{name}! I'm so glad you've come.\n\nWe've been afforded a rare chance to delve into Icecrown Citadel, but we must move quickly if we're to avoid Arthas' notice.", sourceObjectiveStatus = "unverified-source-field" }
quests[24511] = { id = 24511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Tortured Souls", description = "I'm glad we have someone capable to aid us in this. Delving into the citadel with so few is risky at best, but opportunities like this are too rare to pass up.\n\nI'm awaiting the arrival of champions from the coliseum, but if your reputation holds true, you should be more than equipped to fight through the forge yourself. Clear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the Citadel.\n\nBe quick about it, {name}. Time is short.", sourceObjective = "Kill Bronjahm and the Devourer of Souls to secure access to the Pit of Saron.", completion = "Well timed, {class}!\n\nThe Pit of Saron lies ahead, and if our scouts are correct, past that will be the Halls of Reflection. It is there that Arthas lets his guard down, and it is there that we hope to find a clue to his weakness... and a route to vengeance long overdue.", sourceObjectiveStatus = "unverified-source-field" }
quests[24522] = { id = 24522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey To The Sunwell", description = "Take Quel'Delar to the Sunwell as quickly as possible, {name}. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas, and there, seek entry to the Sunwell itself, where you can cleanse the sword.\n\nThe guardians of the Sunwell will not simply allow you to walk in, so you must find Halduron Brightwing, who will be inspecting the guards there.", sourceObjective = "Speak with Halduron Brightwing at the entrance to the Sunwell Plateau on the Isle of Quel'Danas.", progress = "What brings you here?", completion = "Admit you to the Sunwell? That's impossible! The Sunwell is the most sacred and important site of our people. We have only recently reclaimed it with the help of the Shattered Sun Offensive. It is not a place for tourists or travelers.", sourceObjectiveStatus = "unverified-source-field" }
quests[24535] = { id = 24535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalorien Dawnseeker", description = "If you truly bear Quel'Delar, {name}, I might be able to admit you to the Sunwell. If you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.", sourceObjective = "Visit Thalorien Dawnseeker's Remains and obtain his blessing to wield Quel'Delar.", progress = "Did you visit the ground where Thalorien fell defending the Sunwell?", completion = "I confess that I did not expect Thalorien's spirit to recognize you as the heir to Quel'Delar, but I defer to his judgment. You may enter the Sunwell, but I remind you that you are a guest in the most our most sacred of precincts, and you should act accordingly.", sourceObjectiveStatus = "unverified-source-field" }
quests[24536] = { id = 24536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Stinks", description = "Get a load of these guys, would ya? Steamwheedle's been handling the business of holidays for years, and all of a sudden, these guys bust into the market. They're not Steamwheedle; the cartel hired me to get to the bottom of this. Something stinks here and it ain't just perfume.\n\nTake this device I brought and go analyze the perfume clouds around the guards. I want to know what they're putting in that stuff. Things ain't natural.", sourceObjective = "Use Snagglebolt's Air Analyzer to test the air around 6 heavily perfumed guards, then return to Detective Snap Snagglebolt in Orgrimmar.", progress = "You analyze that reek yet, kid?", completion = "Hey, thanks, kid. Give it over, let's take a look.\n\n<He takes the device from you and fiddles with it.>\n\nOh, that ain't good.", sourceObjectiveStatus = "unverified-source-field" }
quests[24541] = { id = 24541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfering Perfume", description = "I knew they were up to no good! There's some sort of mind-affecting chemical in here, but I can't get a handle on it with such a small sample. I need the real stuff.\n\nDon't just go over there and buy it! I don't want you giving these scumbags one copper. Nah, you gotta get it from the source, discreet-like.\n\nI'll disguise you as a package runner. I saw a stockpile guarded by their goons outside the gates. Go run by, and DON'T stop, or they'll make you! They'll toss you a crate. Bring it back here.", sourceObjective = "While disguised as a package-runner, go to the Crown Chemical Company's stockpile outside the gates of Orgrimmar, then return the package they toss you to Detective Snap Snagglebolt in Orgimmar.", progress = "Did they toss ya a crate to deliver?", completion = "You got it, huh? Good job, kid. Top notch. Let's see what we got here.\n\n<He cracks open the crate and rummages around inside.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24545] = { id = 24545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sacred and the Corrupt", description = "It is against my judgment that I present you this errand, {race}, as it will likely end in your undoing.\n\nIgnore my counsel and embark on the endeavor, and I shall provide you with the knowledge and resources to see it through.\n\nYou must return to Frostmourne Cavern and recover Light's Vengeance, Arthas' discarded hammer. Reforged with saronite and etched with the acidic blood of the Lich King's abominations, it will provide the foundation for our work.", sourceObjective = "Place Light's Vengeance, 25 Primordial Saronite, Rotface's Acidic Blood, and Festergut's Acidic Blood in Highlord Mograine's runeforge in Icecrown Citadel.\n\nRotface's Acidic Blood and Festergut's Acidic Blood may only be obtained in the 25 person difficulty setting of Icecrown Citadel.", progress = "As you draw near, the forge's flame seems to burn even more ravenously...", completion = "A deep sense of dread washes over you as the flame devours the items.", sourceObjectiveStatus = "unverified-source-field" }
quests[24547] = { id = 24547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Feast of Souls", description = "Shadow's Edge is among the greatest weapons a {class} could hope to obtain.\n\nIs your lust for power sated, {race}?\n\n<You feel Mograine's penetrating gaze.>\n\nI thought not. A final warning then...\n\nYou now embark on the most treacherous leg of your quest. Bridle your aspirations, for if your aims are impure then your life, your very soul, is forfeit.\n\nThe weapon you hold is but an empty husk, a mere shadow of what it may become. Only by devouring a thousand souls shall its true potential be unlocked.", sourceObjective = "Highlord Darion Mograine wants you to use Shadow's Edge to slay 1000 of the Lich King's minions in Icecrown Citadel. Souls can be obtained in 10 or 25 person difficulty.", completion = "<Highlord Mograine eyes you in silence for a moment.>\n\nYou seem to have endured this leg of your trial admirably, {race}.\n\nPray that fate continues to smile upon you in your endeavor...", sourceObjectiveStatus = "unverified-source-field" }
quests[24548] = { id = 24548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Splintered Throne", description = "The Lich King's throne once served as his prison. Kil'jaeden himself crafted the vessel of icy crystals from the twisting nether, its sole purpose to hold Ner'zhul's vengeful spirit.\n\nWhen Arthas struck the crystal with Frostmourne, he released Ner'zhul's soul, allowing it to merge with his own. Splinters from that impact are now scattered throughout the citadel.\n\nI shall require those shards, held only by the Lich King's most powerful servants, to seal the power contained in your blade.", sourceObjective = "Highlord Darion Mograine wants you to collect 50 Shadowfrost Shards.\n\nShadowfrost Shards may only be obtained in the 25 person difficulty setting.", sourceObjectiveStatus = "unverified-source-field" }
quests[24549] = { id = 24549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmourne...", sourceObjective = "Highlord Darion Mograine wants you to bring him Shadow's Edge.", sourceObjectiveStatus = "unverified-source-field" }
quests[24553] = { id = 24553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to me and to the rest of my people that Quel'Delar has been recovered.\n\nAs promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. The blade will bond to you. When that happens, carry it to Caladis Brightspear at Quel'Delar's Rest.", sourceObjective = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What happened during your time in the Sunwell?", completion = "This is unbelievable, {name}. You've really done it! All of the quel'dorei have heard of Thalorien Dawnseeker and Quel'Delar, but no one ever thought the sword would be restored.", sourceObjectiveStatus = "unverified-source-field" }
quests[24554] = { id = 24554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battered Hilt", description = "This battered old sword hilt has seen better days. Before the hilt was snapped from the blade, it must've been a magnificent example of the blacksmith's art.\n\nThe graceful symbols and exotic gemstones decorating the hilt suggest that the weapon may have belonged to a powerful person. Surely, the Sunreavers would be interested in hearing about the recovery of such an artifact. Seek out their representatives at Quel'Delar's Rest, to the south of the Argent Tournament Grounds.", sourceObjective = "Bring the Battered Hilt to Myralion Sunblaze at Quel'Delar's Rest, south of the Argent Tournament Grounds.", progress = "What have you discovered?", completion = "<Myralion takes the hilt from you and scrutinizes the artifact.>\n\nThis came from the citadel? What was it doing there? This blade is certainly not of Scourge manufacture.\n\nWeapons of this quality can only be crafted by a few of Azeroth's creatures. We will have to consult them and see if they can help us identify it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24555] = { id = 24555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What The Dragons Know", description = "There's no mistaking it - this hilt comes from a powerful, ancient weapon, but which one? I do not recognize these particular markings, but we haven't hit a dead end yet.\n\nKorialstrasz, better known as Krasus, has long been a friend to the quel'dorei and the Kirin Tor. With his vast knowledge and resources, he's certain to know something. Travel to the top of Wyrmrest Temple and seek his counsel, then report to Magister Hathorel inside Sunreaver's Sanctuary in Dalaran.", sourceObjective = "Speak to Krasus at the top of Wyrmrest Temple.", completion = "We must recover that book from the Silver Covenant. Without that book from Krasus, we stand little chance of solving the mystery of the sword in Icecrown or unlocking its power.", sourceObjectiveStatus = "unverified-source-field" }
quests[24556] = { id = 24556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Suitable Disguise", description = "Getting you inside the Silver Enclave will be tougher than it appears. Only those who possess Silver Covenant tabards are permitted entry to sanctuary. If we can get our hands on one, a simple enchantment will do the rest of the work.\n\nOn the balcony above Threads of Fate, you'll find Shandy Glossgleam. I've helped him a few times in the past, so he owes me a favor. He handles laundry for a wide variety of people in the city. Maybe he can find a way to 'lend' you a tabard for a while.", sourceObjective = "Obtain a Borrowed Tabard from Shandy Glossgleam.", progress = "Was Shandy able to help you get a Silver Covenant tabard?", completion = "I knew Shandy would find a way to make it work. Let me get this enchanted and ready for you to use. With any luck, the tabard's owner won't even know it's missing and Shandy will cover the rest of our tracks.", sourceObjectiveStatus = "unverified-source-field" }
quests[24557] = { id = 24557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silver Covenant's Scheme", description = "One of my contacts in the Underbelly caught sight of a Silver Covenant agent gathering information at the Cantrips and Crows Tavern. Silver Covenant members aren't normally found in the sewers, so they must be plotting something.\n\nGo into the Underbelly, find this Silver Covenant agent, and eliminate him. Search the body for any information that might give us a lead on the location of that tome from Wyrmrest. We can't let those simpering Silver Covenant weaklings get it back to Icecrown before we do.", sourceObjective = "Capture the Silver Covenant Orders.", progress = "Did you find anything of use on that agent?", completion = "<Magister Hathorel reads the captured orders.>\n\nThe agent you intercepted was supposed to deliver the Wyrmrest tome to Icecrown, after meeting with one Arcanist Tybalin inside the Silver Enclave. We have to reclaim that book, {name}, and we only have one chance before it leaves the city. We have to work quickly.", sourceObjectiveStatus = "unverified-source-field" }
quests[24558] = { id = 24558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return To Myralion Sunblaze", description = "We must get this book to Myralion Sunblade. Would you bring it to him? I cannot rely on anyone else to transport the book and you have proven adept at evading the Silver Covenant's men.\n\nTake it with you to Quel'Delar's Rest, south of the Argent Tournament Grounds in Icecrown. Myralion will be waiting for you. If he can identify that blade, we may be able to claim it in the name of Aethas Sunreaver and show Dalaran and the Alliance that we will lead the charge against the Lich King.", sourceObjective = "Bring Ancient Dragonforged Blades to Myralion Sunblaze at Quel'Delar's Rest.", progress = "We've been expecting your return. What has kept you?", completion = "<Myralion accepts the heavy book and begins leafing through it.>\n\nThose symbols on the blade seemed familiar and now there's little wonder why. This is certainly a dragon blade, gifted to one of the mortal races, but which blade is this, and how did it come to rest in Icecrown?", sourceObjectiveStatus = "unverified-source-field" }
quests[24559] = { id = 24559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reforging The Sword", description = "We cannot allow Quel'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel.\n\nIn the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel'Delar.\n\nYou must gather bars of infused saronite and capture the forgemaster's hammer, then bring them to the forgemaster's anvil and reforge the sword.", sourceObjective = "Obtain 5 Infused Saronite Bars and the Forgemaster's Hammer, then combine them with the Remnants of Quel'Delar to create the Reforged Quel'Delar.", progress = "Were you able to reconstruct Quel'Delar?", completion = "You have remade the blade of Quel'Delar in defiance of that Blood-Queen Lana'thel's pronouncement! Now, the blade must be tempered before we can show her the folly of her words.", sourceObjectiveStatus = "unverified-source-field" }
quests[24560] = { id = 24560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempering The Blade", description = "At last, the pieces of Quel'Delar are rejoined and the blade is whole, but it cannot see battle until you have tempered it. That jagged saronite edge is brittle and will shatter the moment it strikes anything.\n\nDeep in Icecrown Citadel's Forge of Souls is a place where the blade can safely be tempered. Take Quel'Delar with you to the abode of the Devourer of Souls and look for the crucible. Plunge the blade into the crucible to temper it and bring it back to me. I'll be waiting in The Frozen Halls.", sourceObjective = "Temper the Re-forged Quel'Delar in the Crucible of Souls.", progress = "Until the sword is tempered, it will be useless.", completion = "Tempering the sword should've restored the blade. Why hasn't it worked?", sourceObjectiveStatus = "unverified-source-field" }
quests[24561] = { id = 24561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Halls Of Reflection", description = "You have re-forged and tempered the sword, yet it sits quietly in its sheath, little different from a mundane blade. You say the sword pulls you, as though it possesses a will?\n\nDare you bring it where it wishes to go? It is not right that the sword should be this silent and this insistent, yet I fear that if you do not take the sword to its destination, we will never learn why. Bear it with you to Icecrown Citadel's Halls of Reflection, but be on your guard. I will wait for you in The Frozen Halls.", sourceObjective = "Bring Quel'Delar to Sword's Rest inside the Halls of Reflection.", progress = "What happened inside the Halls of Reflection?", completion = "How can evil take root in such a sword? I would not have thought it possible if the evidence wasn't here before my eyes. If the greatest of dragonkind's creations could be corrupted and turned against them, why not a mere sword?\n\nI believe Uther is right. You must heed his advice quickly, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24562] = { id = 24562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey To The Sunwell", description = "Take Quel'Delar to the Sunwell as quickly as possible, {name}. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas, and there, seek entry to the Sunwell itself, where you can cleanse the sword.\n\nThe guardians will try to stop you from entering the Sunwell Plateau, but make yourself known to Halduron Brightwing, who will be inspecting the guards there.", sourceObjective = "Speak with Halduron Brightwing at the entrance to the Sunwell Plateau on the Isle of Quel'Danas.", progress = "What brings you here?", completion = "I hope you understand that I can't just admit you to the Sunwell, {name}. This is the most sacred place known to the sin'dorei and we have only recently regained control over it.\n\nYou would raise the hopes of our people with tales of Quel'Delar? Without proof of the truth of your claims, I see no reason to take you at your word.", sourceObjectiveStatus = "unverified-source-field" }
quests[24563] = { id = 24563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalorien Dawnseeker", description = "You are the one working with Myralion Sunblaze, arent you? I know of a way we can test the sword.\n\nIf you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.", sourceObjective = "Visit Thalorien Dawnseeker's Remains and obtain his blessing to wield Quel'Delar.", progress = "Did you visit the ground where Thalorien fell defending the Sunwell?", completion = "You truly do carry Quel'Delar. This is a great day for all of Quel'Thalas and the sin'dorei. You have my leave to enter the Sunwell and finish the sword's restoration. Keep your head high, {name}. The children of Silvermoon have dreamt of this day for years.", sourceObjectiveStatus = "unverified-source-field" }
quests[24564] = { id = 24564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Afterward, show the blade to Myralion Sunblaze at Quel'Delar's Rest.", sourceObjective = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What happened inside the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24576] = { id = 24576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friendly Chat...", description = "<Roka listens with disgust as you tell her why you're trying to track down Snivel.>\n\nYou mean I've been under the spell of an alchemist all this time? I can't believe I fell for that fraud! If I ever get my hands on that conniving little goblin, I'll tear him apart!\n\nIf he's finished his errands, he's on his way down to the zeppelin tower east of Orgrimmar's gates! Whatever you do, {name}, you can't let him board that zeppelin and get away with all this!\n\nHurry to the zeppelin tower before you miss him!", sourceObjective = "Go to the zeppelin tower outside Orgrimmar and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.", progress = "Did you find the guy, or did he crawl under a rock?", completion = "You got his ledger? Really? That's great, {name}. There's probably loads of good information in here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24579] = { id = 24579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sartharion Must Die!", description = "Sartharion, the Onyx Guardian, watches over the eggs of the Twilight Dragonflight. He rests within the Obsidian Sanctum in the Chamber of the Aspects underneath Wyrmrest Temple.\n\nThe Council of Six has decreed that Sartharion must die!", sourceObjective = "Kill Sartharion.\n\nThis quest can be completed with any difficulty or size raid.", progress = "Sartharion yet breathes, {class}.", completion = "With Sartharion slain, surely Deathwing and Sinestra's plans are now stalled.", sourceObjectiveStatus = "unverified-source-field" }
quests[24580] = { id = 24580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anub'Rekhan Must Die!", description = "Anub'Rekhan, once-mighty Spider Lord of the nerubian empire, has been taken by the Lich King and corrupted into a state of undeath.\n\nNow a crypt lord, he sits in his parlor in the Arachnid Quarter of Naxxramas, spinning strategies for Kel'Thuzad.\n\nThe Council of Six has decreed that Anub'Rekhan must die!", sourceObjective = "Kill Anub'Rekhan.\n\nThis quest can be completed with any difficulty or size raid.", completion = "Word of your success precedes you, {class}. Anub'Rekhan is no more. You did him a great service, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24581] = { id = 24581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noth the Plaguebringer Must Die!", description = "Noth the Plaguebringer, traitor and coward! Second only to the Lich King himself for the number of souls that have been Scourged!\n\nMake haste to Naxxramas. You will find him within the Plague Quarter hiding behind his undead minions.\n\nDestroy him! The Council of Six has decreed that Noth must die!", sourceObjective = "Kill Noth the Plaguebringer.\n\nThis quest can be completed with any difficulty or size raid.", completion = "That's one less thorn in our side. With Noth destroyed, Scourge research into refining the means of creating the undead will grind to a halt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24582] = { id = 24582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instructor Razuvious Must Die!", description = "Instructor Razuvious smugly struts about the Military Quarter of Naxxramas. It is said that only a death knight personally trained by him could possibly even withstand the prowess of his blade.\n\nYou and your group are going to prove everyone wrong.\n\nThe Council of Six has decreed that Razuvious must die!", sourceObjective = "Kill Instructor Razuvious.\n\nThis quest can be completed with any difficulty or size raid.", completion = "Well done, {class}. The Scourge military command out of Naxxramas has been thrown into disarray by Razuvious's demise.", sourceObjectiveStatus = "unverified-source-field" }
quests[24583] = { id = 24583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patchwerk Must Die!", description = "The so-called \"avatar of war\", Patchwerk is the ultimate abomination. It is also taking a heavy toll upon on our forces in the Dragonblight.\n\nI want you to assemble your companions and enter the Construct Quarter of Naxxramas. Disassemble the construct.\n\nThe Council of Six has decreed that Patchwerk must die!", sourceObjective = "Kill Patchwerk.\n\nThis quest can be completed with any difficulty or size raid.", completion = "Children everywhere will sleep easier knowing that Patchwerk is no more.", sourceObjectiveStatus = "unverified-source-field" }
quests[24584] = { id = 24584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malygos Must Die!", description = "Our resources are strained. Malygos, the Spell-Weaver, is draining all of the magic out of the world, consolidating it in the Eye of Eternity. Without magic, we are doomed.\n\n{class}, the Nexus War must be brought to an end. The Council of Six has decreed that Malygos must die!", sourceObjective = "Kill Malygos.\n\nThis quest can be completed with any difficulty or size raid.", completion = "With Malygos defeated, the Nexus War should come to a swift conclusion. You have the gratitude of the Kirin Tor, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24585] = { id = 24585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flame Leviathan Must Die!", description = "Within the Formation Grounds sits Ulduar's first line of defense: Flame Leviathan.\n\nThe Kirin Tor have been provided with information suggesting that this Keeper-created machine is soon to be transported to an undisclosed location and let loose to wreak havoc upon the mortals of Azeroth.\n\nThis must not come to pass. The Council of Six has decreed that Flame Leviathan must die!", sourceObjective = "Kill Flame Leviathan.\n\nThis quest can be completed with any difficulty or size raid.", completion = "I never cease to be amazed by the horrors that can be created through the use of technology.", sourceObjectiveStatus = "unverified-source-field" }
quests[24586] = { id = 24586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razorscale Must Die!", description = "Razorscale normally keeps to her aerie near the Colossal Forge in Ulduar. Of late, however, she has been spotted reigning fire down upon lands outside of the titan complex.\n\nThough the broodmother's is a sad tale, she poses an imminent threat to all of Northrend. The Council of Six has decreed that Razorscale must die!", sourceObjective = "Kill Razorscale.\n\nThis quest can be completed with any difficulty or size raid.", completion = "Now Veranus can finally rest in peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[24587] = { id = 24587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignis the Furnace Master Must Die!", description = "The great fire giant, Ignis the Furnace Master toils away inside of Ulduar's Colossal Forge. Under orders from Loken, Ignis creates weapons that are terrifying in their power.\n\nThe Council of Six has decreed that Ignis must die!", sourceObjective = "Kill Ignis the Furnace Master.\n\nThis quest can be completed with any difficulty or size raid.", completion = "I trust that you did not have to face too many of his iron construct assistants?", sourceObjectiveStatus = "unverified-source-field" }
quests[24588] = { id = 24588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "XT-002 Deconstructor Must Die!", description = "Yet another strange construct of Mimiron, the XT-002 Deconstructor actually thinks that it is the keeper's son. Do not be fooled by its feigned innocence. It is a deadly machine!\n\nYou will find the Deconstructor within Ulduar's Scrapyard. The Council of Six has decreed that XT-002 Deconstructor must die!", sourceObjective = "Kill XT-002 Deconstructor.\n\nThis quest can be completed with any difficulty or size raid.", completion = "The greatest weakness of Ulduar is its masters' blind faith in their inventions to protect it.", sourceObjectiveStatus = "unverified-source-field" }
quests[24589] = { id = 24589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Jaraxxus Must Die!", description = "Archmage Timear has foreseen a horrible event, which is about to transpire. A foolish gnome warlock is about to accidentally summon an Eredar lord of the Burning Legion into the middle of the Trial of the Crusader.\n\nYou must be there when it happens, {class}. If Lord Jaraxxus escapes, he will open a portal and the Burning Legion will spill forth into our world once more.\n\nThe Council of Six has decreed that Lord Jaraxxus must die!", sourceObjective = "Kill Lord Jaraxxus.\n\nThis quest can be completed with any difficulty or size raid.", completion = "All of Azeroth is fortunate that Timear foresaw the Eredar lord's arrival and that you were there in time to slay him.", sourceObjectiveStatus = "unverified-source-field" }
quests[24590] = { id = 24590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Marrowgar Must Die!", description = "Lord Marrowgar is the guardian of the Frozen Throne within the Spire Chamber. Pieced together by the Lich King from the bones of a thousand vanquished adventurers, Marrowgar wields the power of the throne itself.\n\nWithout the destruction of this bone wraith, there is no hope of taking Icecrown Citadel.\n\nThe Council of Six has decreed that Lord Marrowgar must die!", sourceObjective = "Kill Lord Marrowgar.\n\nThis quest can be completed with any difficulty or size raid.", completion = "The Frozen Throne is without its chief guardian thanks to you. Our attacks upon the Lich King's forces will be all the more successful now.", sourceObjectiveStatus = "unverified-source-field" }
quests[24594] = { id = 24594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Speak to a Warden of the Sunwell to enter the Sunwell Plateau. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Show the blade to Myralion Sunblaze at Quel'Delar's Rest once it is restored.", sourceObjective = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "You have returned from the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24595] = { id = 24595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to my people that Quel'Delar has been recovered.\n\nAs promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. Once the blade is restored, return with it to Caladis Brightspear at Quel'Delar's Rest.", sourceObjective = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "Tell me of what happened in the Sunwell, {name}.", completion = "This is unbelievable, {name}. You've really done it! All of the quel'dorei have heard of Thalorien Dawnseeker and Quel'Delar, but no one ever thought the sword would be restored.", sourceObjectiveStatus = "unverified-source-field" }
quests[24596] = { id = 24596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete the its restoration, then speak with Myralion Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", sourceObjective = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", sourceObjectiveStatus = "unverified-source-field" }
quests[24597] = { id = 24597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the King of Stormwind", description = "Did you want to make a Lovely Charm Bracelet for the king of Stormwind? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to King Varian Wrynn in Stormwind.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24598] = { id = 24598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete its restoration, then show it to Myralio Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", sourceObjective = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", sourceObjectiveStatus = "unverified-source-field" }
quests[24609] = { id = 24609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the Lord of Ironforge", description = "Did you want to make a Lovely Charm Bracelet for the Lord of Ironforge? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to King Magni Bronzebeard in Ironforge.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24610] = { id = 24610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the High Priestess of Elune", description = "Did you want to make a Lovely Charm Bracelet for the High Priestess of Elune? I'm sure she'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Tyrande Whisperwind in Darnassus.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24611] = { id = 24611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the Prophet", description = "Did you want to make a Lovely Charm Bracelet for the Prophet of the Exodar? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Prophet Velen in the Exodar.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24612] = { id = 24612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the Warchief", description = "Did you want to make a Lovely Charm Bracelet for the Warchief? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Thrall in Orgrimmar.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24613] = { id = 24613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the Banshee Queen", description = "Did you want to make a Lovely Charm Bracelet for the Banshee Queen? I'm sure she'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Lady Sylvanas Windrunner in Undercity.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24614] = { id = 24614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the High Chieftain", description = "Did you want to make a Lovely Charm Bracelet for the High Chieftain? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Cairne Bloodhoof in Thunder Bluff.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24615] = { id = 24615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for the Regent Lord of Quel'Thalas", description = "Did you want to make a Lovely Charm Bracelet for the Regent Lord of Quel'Thalas? I'm sure he'd be thrilled.\n\nDo you already have a Lovely Charm Collector's Kit?", sourceObjective = "Present a Lovely Charm Bracelet to Lor'themar Theron in Silvermoon City.", progress = "Well met, {class}. Did you have something for me?", completion = "My thanks for this Lovely Charm Bracelet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24629] = { id = 24629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Puff of Perfume", description = "You look like a real go-getter, {class}. How about we work out a little win-win scenario?\n\nCrown's looking to offer samples of our latest holiday-themed products to as many potential customers as possible. Help us share the love, and we'll give you discounts on some great Crown merchandise!\n\nYour time, our money, friend. What do you say?", sourceObjective = "Spray 10 people with the Crown Perfume Sprayer.", completion = "Great work, {name}! People will come running to buy Crown perfumes now that they've had a chance to sample their wonders.\n\nHere's a little something for helping us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[24635] = { id = 24635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cloudlet of Classy Cologne", description = "You seem the enterprising sort, {class}. How about we make a little deal?\n\nCrown wants to offer samples of our latest holiday-themed products to as many potential customers as we can. Help us share the love while earning some fantastic Crown merchandise!\n\nYour time, our money, friend. What do you think?", sourceObjective = "Spray 10 people with the Crown Cologne Sprayer.", progress = "That cologne isn't going to give itself out, you know.\n\nGet spraying!", completion = "Nice work, {name}! People will be buying Crown colognes by the crate-load now that they've had a chance to try them.\n\nHere's a little something for helping us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[24636] = { id = 24636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonbon Blitz", description = "I can see you've got an eye for opportunity, {class}. What do you say we make a little coin together?\n\nCrown needs to push samples of our latest holiday-themed products to every potential customer in the city. Help us share the love, and we'll share some of that amazing Crown merchandise with you!\n\nYour time, our money, friend. We got a deal?", sourceObjective = "Toss 10 people samples from the Crown Chocolate Sampler.", progress = "You know, those chocolates aren't going to fling themselves at people.\n\nYou need to get to work!", completion = "Lovely work, {name}! People will be tripping over one another to get Crown chocolates now that they've had a chance to taste those sweet, romantic treats.\n\nHere's a little something for helping us out.", sourceObjectiveStatus = "unverified-source-field" }
quests[24638] = { id = 24638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's right outside Orgrimmar's gates, to the west! That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon just west of Orgrimmar's gates in Durotar, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24645] = { id = 24645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just outside Ambermill in Silverpine Forest. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Thugs and use Snagglebolt's Khorium Bomb to destroy one chemical wagon outside of Ambermill in Silverpine Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24647] = { id = 24647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just outside the village of Hillsbrad in -- you guessed it -- Hillsbrad Foothills. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Dusters and use Snagglebolt's Khorium Bomb to destroy one chemical wagon just outside of Hillsbrad Village in Hillsbrad Foothills, then return to Detective Snap Snagglebolt in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24648] = { id = 24648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's near Sentry Point, just outside Theramore in Dustwallow. Don't give me that look, okay? This is a problem for us, too. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Hoodlums and use Snagglebolt's Khorium Bomb to destroy one chemical wagon outside of Theramore in Dustwallow Marsh, then return to Detective Snap Snagglebolt in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24649] = { id = 24649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's to the east of Aerie Peak in the Hinterlands. Don't give me that look, okay? This is a problem for the Horde, too. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Agents and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Aerie Peak in the Hinterlands, then return to Detective Snap Snagglebolt in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24650] = { id = 24650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's in Winterspring, just east of Everlook. Oh, now this is personal. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Sprinklers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Everlook in Winterspring, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24651] = { id = 24651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's just east of Shattrath, in Terokkar Forest. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Underlings and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Shattrath City in Terokkar Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24652] = { id = 24652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's in the Forlorn Woods of Crystalsong, northwest of the Mirror of Twilight. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Sprayers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon in the Forlorn Woods of Crystalsong Forest, then return to Detective Snap Snagglebolt in Orgrimmar.", progress = "Did you teach 'em a lesson?", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24655] = { id = 24655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Stinks", description = "Get a load of these guys, would ya? Steamwheedle's been handling the business of holidays for years, and all of a sudden, these guys bust into the market. They're not Steamwheedle; the cartel hired me to get to the bottom of this. Something stinks here and it ain't just perfume.\n\nTake this device I brought and go analyze the perfume clouds around the guards. I want to know what they're putting in that stuff. Things ain't natural.", sourceObjective = "Use Snagglebolt's Air Analyzer to test the air around 6 heavily perfumed guards, then return to Inspector Snip Snagglebolt in Stormwind.", progress = "You analyze that reek yet, kid?", completion = "Hey, thanks, kid. Give it over, let's take a look.\n\n<He takes the device from you and fiddles with it.>\n\nOh, that ain't good.", sourceObjectiveStatus = "unverified-source-field" }
quests[24656] = { id = 24656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilfering Perfume", description = "I knew they were up to no good! There's some sort of mind-affecting chemical in here, but I can't get a handle on it with such a small sample. I need the real stuff.\n\nDon't just go over there and buy it! I don't want you giving these scumbags one copper. Nah, you gotta get it from the source, discreet-like.\n\nI'll disguise you as a package runner. I saw a stockpile guarded by their goons outside the gates. Go run by, and DON'T stop, or they'll make you! They'll toss you a crate. Bring it back here.", sourceObjective = "While disguised as a package-runner, go to the Crown Chemical Company's stockpile outside the gates of Stormwind, then return the package they toss you to Inspector Snip Snagglebolt in Stormwind.", progress = "Did they toss ya a crate to deliver?", completion = "You got it, huh? Good job, kid. Top notch. Let's see what we got here.\n\n<He cracks open the crate and rummages around inside.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24657] = { id = 24657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friendly Chat...", description = "<Marion listens with horror as you tell her why you're trying to track down Snivel.>\n\nYou mean, he might've used some kind of chemical on me? Ew! I can't believe I fell for that fraud!\n\nIf he's finished all of his errands, he's on his way down to the docks to catch a ship to the South Seas! Whatever you do, {name}, you can't let him get away with this.\n\nHurry down to Stormwind Harbor before you miss him!", sourceObjective = "Go to Stormwind Harbor and question Snivel Rustrocket about the supplies. Return with any evidence he gives you.", progress = "Did you find the guy, or did he crawl under a rock?", completion = "You got his ledger? Really? That's great, {name}. There's probably loads of good information in here.", sourceObjectiveStatus = "unverified-source-field" }
quests[24658] = { id = 24658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's northeast of Westbrook Garrison right outside in Elwynn! That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon northeast of Westbrook Garrison in Elwynn Forest, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24659] = { id = 24659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just south of the Grove of the Ancients in Darkshore. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Thugs and use Snagglebolt's Khorium Bomb to destroy one chemical wagon south of the Grove of the Ancients in Darkshore, then return to Inspector Snip Snagglebolt in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[24660] = { id = 24660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's just outside the village of Hillsbrad in -- you guessed it -- Hillsbrad Foothills. That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Dusters and use Snagglebolt's Khorium Bomb to destroy one chemical wagon just outside of Hillsbrad Village in Hillsbrad Foothills, then return to Inspector Snip Snagglebolt in Stormwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[24661] = { id = 24661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's right outside Orgrimmar's gates, to the west! That can't be good. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon just west of Orgrimmar's gates in Durotar, then return to Detective Snap Snagglebolt in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24662] = { id = 24662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's near Sentry Point, just outside Theramore in Dustwallow. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Hoodlums and use Snagglebolt's Khorium Bomb to destroy one chemical wagon outside of Theramore in Dustwallow Marsh, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24663] = { id = 24663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's to the east of Aerie Peak in the Hinterlands. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Agents and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Aerie Peak in the Hinterlands, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24664] = { id = 24664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it's in Winterspring, just east of Everlook. Oh, now this is personal. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Sprinklers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Everlook in Winterspring, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24665] = { id = 24665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's just east of Shattrath, in Terokkar Forest. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Underlings and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of Shattrath City in Terokkar Forest, then return to Inspector Snip Snagglebolt in Stormwind.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24666] = { id = 24666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's in the Forlorn Woods of Crystalsong, northwest of the Mirror of Twilight. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", sourceObjective = "Kill 5 Crown Sprayers and use Snagglebolt's Khorium Bomb to destroy one chemical wagon in the Forlorn Woods of Crystalsong Forest, then return to Inspector Snip Snagglebolt in Stormwind.", progress = "Did you teach 'em a lesson?", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24682] = { id = 24682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pit of Saron", description = "Quickly, through the portal! I'll find you on the other side.", sourceObjective = "Meet Lady Sylvanas Windrunner inside the entrace to the Pit of Saron.", completion = "Incapable fools. I begin to wonder if any of these louts from the tournament will be of any use at all. Perhaps you'll prove me wrong.", sourceObjectiveStatus = "unverified-source-field" }
quests[24683] = { id = 24683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pit of Saron", description = "Quickly, through the portal! I'll meet you on the other side.", sourceObjective = "Meet Lady Jaina Proudmoore just inside the Pit of Saron.", completion = "I underestimated this Scourgelord, and it's my men that paid for it. When I think that my guilt over Arthas' betrayal cannot go any deeper, he proves me wrong yet again.\n\nWe have to press on. We cannot let their sacrifice be meaningless.", sourceObjectiveStatus = "unverified-source-field" }
quests[24710] = { id = 24710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliverance from the Pit", description = "We need to make our way up the main path and through the cave to Tyrannus' rise. There, he will be forced to confront us there lest we make our way into the citadel proper.\n\nGo now, {class}. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", sourceObjective = "Kill Scourgelord Tyrannus.", completion = "Such a senseless waste! Arthas goes too far! I can only hope what we find in the Halls of Reflection makes this somehow worth it.\n\nIf what that vile gnome said is to be trusted, Frostmourne should be there, and with it, answers to confronting Arthas.", sourceObjectiveStatus = "unverified-source-field" }
quests[24711] = { id = 24711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmourne", description = "We must press on, hero. We've come so far... we're so close to our goal. I must delay a moment to send Elandra back to the airship. I'm uncertain how we're going to escape with so many men lost and so few to keep our path in secure - we will need any help they can send.\n\nContinue on. I will meet you in the Halls of Reflection.", sourceObjective = "Meet Lady Jaina Proudmoore at the entrance to the Halls of Reflection.", completion = "The Halls of Reflection. Finally.\n\nLet me know when you are ready. Arthas may not be here, but it would be naive to think that he would leave Frostmourne unguarded entirely.", sourceObjectiveStatus = "unverified-source-field" }
quests[24712] = { id = 24712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliverance from the Pit", description = "We need to make our way up the main path and through the cave to Tyrannus' rise. There, he will be forced to confront us there lest we make our way into the citadel proper.\n\nGo now, {class}. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", sourceObjective = "Kill Scourgelord Tyrannus.", completion = "The Halls of Reflection lie ahead. If what that vile gnome said is to be trusted, Frostmourne should be there, and with it, answers to confronting Arthas.", sourceObjectiveStatus = "unverified-source-field" }
quests[24713] = { id = 24713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmourne", description = "Keep moving, the sword is close.\n\nI need a moment to send one of my Dark Rangers back to the airship. With all of our fodder gone, I will not be caught unprepared - we will need any help they can send.\n\nGo. I will meet you in the Halls of Reflection.", sourceObjective = "Meet Lady Sylvanas Windrunner inside the entrance to the Halls of Reflection.", completion = "The Halls of Reflection. Finally.\n\nLet me know when you are ready, {class}. I will not be so naive as to think that Arthas left his precious sword entirely unguarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[24743] = { id = 24743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow's Edge", sourceObjective = "Listen well, {class}. In accepting this weapon your fate is sealed.\n\nOvercome or succumb.\n\nI have placed your feet upon this path. You are therefore my personal responsibility. Should you falter, I am duty-bound to deliver you from this life.\n\nRemember my words, {race}, and do not fail.", sourceObjectiveStatus = "unverified-source-field" }
quests[24745] = { id = 24745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something is in the Air (and it Ain't Love)", description = "The inside of the card is scribbled with mad, detailed plans to infect most of Azeroth.  You should show this to one of Steamwheedle's investigators immediately!", sourceObjective = "Bring the Faded Lovely Greeting Card to Inspector Snip Snagglebolt in Stormwind.", progress = "Did you take care of those no-good scheming villains?", completion = "What've you got there?\n\nOh hey, this is big. Real big. Most of the crazy details in one little package. Thanks - you really helped us reel this all in. Good working with ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[24746] = { id = 24746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[24748] = { id = 24748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lich King's Last Stand", description = "Shadowmourne; a newly forged weapon already steeped in this world's history, reborn into an unrivaled destiny.\n\nWith this weapon you bear a solemn responsibility, and the time to carry out that charge is at hand.\n\nTake this weapon of myth and legend and march on the enemy. Avenge the countless heroes lost in his merciless campaign. Bring rest to their tortured souls.\n\nSteel yourself, {class}, and guide Shadowmourne to fulfill the purpose of its creation.", sourceObjective = "Highlord Darion Mograine in Icecrown Citadel wants you to kill the Lich King.", sourceObjectiveStatus = "unverified-source-field" }
quests[24749] = { id = 24749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unholy Infusion", description = "Before your weapon can reach its full potential it must be endowed with its signature powers. First among them is unholiness.\n\nYou must seek out and defeat the one called Professor Putricide, but his death is not your only goal. You must use his resources against him.\n\nFind a way to absorb his mutated slime. Use the foul substance to infuse your weapon with the power of the unholy. Only when this has been done shall I reveal your next task.", sourceObjective = "Highlord Darion Mograine wants you to infuse Shadow's Edge with Unholy power and slay Professor Putricide.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", completion = "Well done, {class}.\n\nThe completion of our work draws near.", sourceObjectiveStatus = "unverified-source-field" }
quests[24756] = { id = 24756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Infusion", description = "Your weapon is ready to be endowed with the power of blood.\n\nYou must face Queen Lana'thel in battle and subject yourself to her Blood Mirror. This will cause Shadow's Edge to drink the blood of the nearest living being. That being would be you, {race}.\n\nOnce the blade has been thus awakened, allow the Queen's Frenzied Bloodthirst to take hold of you, feed the blade thrice to sate it, and then give the queen an ignominious death.\n\nMay her screams pierce the ears of the Lich King as he awaits his fate.", sourceObjective = "Highlord Darion Mograine wants you to infuse Shadow's Edge with blood and defeat Queen Lana'thel.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", sourceObjectiveStatus = "unverified-source-field" }
quests[24757] = { id = 24757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Infusion", description = "Shadow's Edge is prepared to receive its final infusion of power.\n\nSindragosa, the enemy's own mount, must fall. But before she is brought down, you must sustain four of her frozen breath attacks without tasting death.\n\nWithout his dragon, nothing shall stand between you and the Lich King.", sourceObjective = "Highlord Darion Mograine has instructed you to slay Sindragosa after subjecting yourself to 4 of her breath attacks while wielding Shadow's Edge.\n\nThis quest may only be completed in 25 person difficulty of Icecrown Citadel.", sourceObjectiveStatus = "unverified-source-field" }
quests[24788] = { id = 24788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Heroic Random (1st)" }
quests[24789] = { id = 24789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Heroic Random (Nth)" }
quests[24790] = { id = 24790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Normal Random (1st)" }
quests[24791] = { id = 24791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Normal Random (Nth)" }
quests[24792] = { id = 24792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man on the Inside", description = "You look like you're fit enough to take on the mastermind behind this operation. The ledger says he's holed up in Shadowfang Keep, so that's where I'm sending you.\n\nWe have a man there already but he's not fit to take down an operation by himself. Head on in; the investigator will meet you there. And bring friends.", sourceObjective = "Report to Investigator Fezzen Brasstacks in Shadowfang Keep.", completion = "Fantastic. Help is exactly what I need.", sourceObjectiveStatus = "unverified-source-field" }
quests[24793] = { id = 24793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man on the Inside", description = "You look like you're fit enough to take on the mastermind behind this operation. The ledger says he's holed up in Shadowfang Keep, so that's where I'm sending you.\n\nWe have a man there already but he's not fit to take down an operation by himself. Head on in; the investigator will meet you there. And bring friends.", sourceObjective = "Report to Investigator Fezzen Brasstacks in Shadowfang Keep.", completion = "Fantastic. Help is exactly what I need.", sourceObjectiveStatus = "unverified-source-field" }
quests[24795] = { id = 24795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Victory For The Silver Covenant", description = "In spite of Queen Lana'thel's boasting, you have restored Quel'Delar, {name}. Long have we dreamt of reclaiming Quel'Delar.\n\nThe Silver Covenant, and indeed all quel'dorei owe you a debt of gratitude.\n\nAs a {class}, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? Perhaps the Argent Crusade can find one. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Silver Covenant.", sourceObjective = "Bring the Restored Quel'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.", progress = "Is it true that you have restored Quel'Delar?", completion = "That a weapon of such power has been redeemed from the clutches of evil is a great omen in these times, {name}. With Quel'Delar and staunch Silver Covenant allies at our side, the Lich King will have good reason to fear.\n\nThe crusade maintains an arsenal of exceptional weapons for our strongest allies. Allow me to offer you your choice from among them in return for entrusting us with the care of Quel'Delar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24796] = { id = 24796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Victory For The Silver Covenant", description = "In spite of Queen Lana'thel's boasting, you have restored Quel'Delar, {name}. Long have we dreamt of reclaiming Quel'Delar.\n\nThe Silver Covenant, and indeed all quel'dorei owe you a debt of gratitude.\n\nVereesa Windrunner, the leader of the Silver Covenant, asked to see you after you returned from the Sunwell. Take Quel'Delar with you and go to Dalaran's Violet Citadel where she waits, {name}.", sourceObjective = "Bring the Restored Quel'Delar to Vereesa Windrunner at the Violet Citadel in Dalaran.", progress = "Is it true that you have restored Quel'Delar?", completion = "This is nothing short of an amazing accomplishment, {name}. The day that Thalorien and Anasterian fell, the same day that Quel'Delar was lost, was one of the darkest of my life. To see Quel'Delar restored... it is beyond words.\n\nWithout a doubt, you are meant to be the true bearer of the blade. Quel'Delar's magic is already adapting the blade to your skills and your strengths.", sourceObjectiveStatus = "unverified-source-field" }
quests[24797] = { id = 24797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[24798] = { id = 24798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Victory For The Sunreavers", description = "At last, Quel'Delar is restored for the glory of the Sunreavers and the sin'dorei!\n\nAll of Silvermoon will celebrate you as a hero, {name}.\n\nAs a {class}, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? No worthy sin'dorei has come forward. Let us seek the Argent Crusade's counsel. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Sunreavers.You will be able to choose one of these rewards:", sourceObjective = "Bring the Restored Quel'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.", sourceObjectiveStatus = "unverified-source-field" }
quests[24799] = { id = 24799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Victory For The Sunreavers", description = "At last, Quel'Delar is restored for the glory of the Sunreavers!\n\nAll the Horde will celebrate you as a hero, {name}.\n\nAs a {class}, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? I will not conceal my disappointment; I had hoped it would be a worthy sin'dorei. Let us seek the Argent Crusade's counsel. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Sunreavers.You will be able to choose one of these rewards:", sourceObjective = "Bring the Restored Quel'Delar to Justicar Mariel Trueheart at the Argent Tournament Grounds.", sourceObjectiveStatus = "unverified-source-field" }
quests[24800] = { id = 24800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Victory For The Sunreavers", description = "At last, Quel'Delar is restored for the glory of the Sunreavers and the sin'dorei! All of Silvermoon will proclaim you a hero, as will all of the Horde.\n\nArchmage Aethas Sunreaver, the leader of the Sunreavers, asked to see you after you returned from the Sunwell. Travel to the Violet Citadel in Dalaran as soon as you can, {name} and bring Quel'Delar with you. The archmage wishes to congratulate you personally!", sourceObjective = "Bring the Restored Quel'Delar to Archmage Aethas Sunreaver at the Violet Citadel in Dalaran.", progress = "Is it true that you have restored Quel'Delar?", completion = "Quel'Delar rises again, as we sin'dorei have risen from the ashes of defeat and betrayal. The heart and the weapon of Thalorien Dawnseeker are both with you, {name}.\n\nI see the blade has already started adapting itself to your strengths, {name}. Hold your head high and always keep Quel'Delar at your side.", sourceObjectiveStatus = "unverified-source-field" }
quests[24801] = { id = 24801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Victory For The Sunreavers", description = "At last, Quel'Delar is restored for the glory of the Sunreavers and the Horde! This is a blessing for our efforts against the Lich King.\n\nArchmage Aethas Sunreaver, the leader of the Sunreavers, asked to see you after you returned from the Sunwell. Travel to the Violet Citadel in Dalaran as soon as you can, {name} and bring Quel'Delar with you. The archmage wishes to congratulate you personally!", sourceObjective = "Bring the Restored Quel'Delar to Archmage Aethas Sunreaver at the Violet Citadel in Dalaran.", progress = "Is it true that you have restored Quel'Delar?", completion = "Quel'Delar rises again, as the sin'dorei have risen from the ashes of defeat and betrayal. Yet, somehow, the weapon of Thalorien Dawnseeker has chosen to serve an outsider.\n\nBe at ease, {name}. I do not mean to diminish your accomplishment, for you have done what none of my brothers could, although I do not know why. You are clearly meant to be its bearer; the blade is already adapting itself to your abilities. Wield Quel'Delar proudly against our common foes.", sourceObjectiveStatus = "unverified-source-field" }
quests[24802] = { id = 24802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King", description = "Uther knew a great deal about how Arthas might be defeated. It's hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that?\n\nMany questions remain, but the answers that you've uncovered may be critical to ensuring Arthas' defeat. You need to find Sylvanas and escape the Lich King while there's still time.", sourceObjective = "Find Lady Sylvanas Windrunner and escape the Halls of Reflection", completion = "Yet again, vengeance slips through my grasp. It's hard to believe how much stronger he's gotten.\n\nIt was foolish of you to come for me, but it's good to know that there are still some champions of the Horde that aren't useless cowards. The information Uther gave us may well be key to finally killing Arthas, though it is becoming more and more clear that the Horde will not be able to accomplish this on their own.\n\nGo, {class}. I expect your prowess may be needed again very soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[24803] = { id = 24803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalu'ak Fishing Derby", progress = "The Kalu'ak have a long tradition of honing our fishing skills by putting them to the test every week.\n\nThe first person to catch and bring a blacktip shark to me will be rewarded handsomely, and be known as the greatest fisherman of the north... for a couple days at least.\n\nThe blacktip shark's favorite food is the pygmy suckerfish.  Try fishing for the blacktip wherever you would normally catch the suckerfish.", completion = "Don't just stand there!  Give me the shark and I'll declare you the winner!" }
quests[24804] = { id = 24804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncommon Scents", description = "Something's not right about this Crown Chemical Company. Steamwheedle's got eyes on 'em, and we could use a few more.\n\nHead to Stormwind if you're interested in helping us out. Inspector Snip Snagglebolt is heading up the investigation there, and he can use all the help he can get.", sourceObjective = "Report to Inspector Snip Snagglebolt in Stormwind.", completion = "Hey. You got some time on your hands? I could use someone like you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24805] = { id = 24805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncommon Scents", description = "Something's not right about this Crown Chemical Company. Steamwheedle's got eyes on 'em, and we could use a few more.\n\nHead to Orgrimmar if you're interested in helping us out. Detective Snap Snagglebolt is heading up the investigation there, and he can use all the help he can get.", sourceObjective = "Report to Detective Snap Snagglebolt in Orgrimmar.", completion = "Hey. You got some time on your hands? I could use someone like you.", sourceObjectiveStatus = "unverified-source-field" }
quests[24806] = { id = 24806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Better Luck Next Time", progress = "I'm afraid we've already had a winner for today, young {name}.  However, if you bring a shark, I'll see that it's released back into the waters, and I might just have a little something for you...", completion = "Well, it's nice that you tried {race}.  I don't want you to think your efforts were wasted, so I've got something for you." }
quests[24815] = { id = 24815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choose Your Path", sourceObjective = "To atone for the sins I committed as one of the Lich King's Death Knights, I've dedicated myself to creating rings of great power for our brothers and sisters to use in the struggle.\n\nYou've proven yourself as a valuable ally in the fight against the Scourge, {name}.  As your dedication continues I can improve on the ring's original design.\n\nChoose your path carefully.  A change of heart will come at a price.", sourceObjectiveStatus = "unverified-source-field" }
quests[24819] = { id = 24819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Change of Heart", progress = "You seek to change the path you walk, {name}?", completion = "May you find what you're looking for, brother." }
