quests[24848] = { id = 24848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fireworks At The Gilded Rose", description = "Kid, this is about more than just perfume. There were some rockets in that crate, and they had some kind of chemical payload inside. I can't analyze it here, but I'll spare ya the trip to the lab.\n\nNah, you gotta find the guy who made these. I know the maker's mark. Snivel Rustrocket.\n\nI got a tip from a reliable source that Snivel's here in Stormwind, livin' it up at the Gilded Rose. What's more, he had some dame on his arm. Marion Sutton was the name. Go to the Gilded Rose and see what she knows.", sourceObjective = "Speak to Marion Sutton at the Gilded Rose in Stormwind's Trade District.", completion = "You... You're not Snivel. Did he send you? He's so late, I had started to give up hope...\n\n<Tears start welling up in the woman's eyes once she realizes that you aren't there to deliver a message from Snivel.>\n\nThat's not like my Snivel, but what other choice is there?", sourceObjectiveStatus = "unverified-source-field" }
quests[24849] = { id = 24849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot On The Trail", description = "I'd better start from the beginning. It was love at first sight, {name}. There was just something about that goblin from the moment I set eyes on him.\n\nAfter a wonderful week together, Snivel said he had come into a lot of money and that he was going to take me on a long vacation to the South Seas! Can you believe it?\n\nAnyway, he told me to pack while he ran some errands to the bank, the auction house, and the barber shop, but he never came back! I'm beginning to think he's nothing but a big liar!", sourceObjective = "Look for Snivel Rustrocket in the Stormwind Counting House, the Auction House, and the Barbershop in Stormwind City.", progress = "Did you find him?", completion = "All he talked about was leaving town with all his money? Then he really has abandoned me, hasn't he?\n\nOh, {name}, I was such a fool to fall for him, but how could I help myself? He was so irresistible!", sourceObjectiveStatus = "unverified-source-field" }
quests[24850] = { id = 24850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snivel's Sweetheart", description = "Kid, this is about more than just perfume. There were some rockets in that crate, and they had some kind of chemical payload inside. I can't analyze it here, but I'll spare ya the trip to the lab.\n\nNah, you gotta find the guy who made these. I know the maker's mark. Snivel Rustrocket.\n\nI hear Snivel's livin' it up here in Orgrimmar. What's more, he's got himself a girlfriend -- some orc dame named Roka. She's supposed to meet him at Gotri's Travelling Goods in the Drag before they make their escape.", sourceObjective = "Speak to Roka at the Gotri's Travelling Goods in Orgrimmar's Drag district.", completion = "You're not Snivel. He was supposed to be here an hour ago! What have you done with him?\n\n<Roka seems to calm down when you tell her that you're looking for Snivel, too. Then, tears start to well up in her eyes.>\n\nThis isn't like my sweet Snivel. Do you think something's happened to him?", sourceObjectiveStatus = "unverified-source-field" }
quests[24851] = { id = 24851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot On The Trail", description = "I'd better start from the beginning. It was love at first sight, {name}. There was just something about that goblin from the moment I set eyes on him.\n\nAfter a wonderful week together, Snivel said he had come into a lot of money and that he was going to take me on a long vacation to the South Seas! Can you believe it?\n\nAnyway, he told me to pack while he ran some errands to the bank, the auction house, and the barber shop, but he never came back! I'm beginning to think he's nothing but a big liar!", sourceObjective = "Look for Snivel Rustrocket in the Orgrimmar Bank, the Auction House, and the Barbershop in Orgrimmar.", progress = "Did you find him?", completion = "All he talked about was leaving town with all his money? Then he really has abandoned me, hasn't he?\n\nI can't believe I fell for such a horrible goblin! But he was so irresistible when we first met.", sourceObjectiveStatus = "unverified-source-field" }
quests[24857] = { id = 24857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Camp Narache", description = "After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache.\n\nSurely Chief Hawkwind could use this information!", sourceObjective = "Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache.", progress = "You have a look of concern about you, {name}. What news do you bring?", completion = "This is quite alarming indeed! But with this information we can call on our brethren from Bloodhoof Village to help thwart the attack. You have saved the lives of many {race}, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24869] = { id = 24869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deprogramming", description = "We had hoped to place a man on the inside of the Cult of the Damned, to give us an inside angle on the Lich King's machinations, but we... underestimated the persuasive powers of Arthas and his dark minister, Lady Deathwhisper.\n\nOur man, Darnavan, is one of them now.\n\nIf you plan on fighting your way through the Oratory ahead, please keep your eyes peeled for Darnavan. If you can bring him back to us alive, we can attempt to reverse the Cult's brainwashing.", sourceObjective = "Defeat Lady Deathwhisper while ensuring that Darnavan survives.", progress = "Darnavan has been among the Cult for so long now that there is no telling how he will react. He is a well-trained warrior, so be on your guard!", completion = "Thank you, {name}!\n\nI owe you a debt of gratitude for rescuing a friend whom I had thought forever lost to the clutches of the Cult. And the Argent Crusade owes you a debt for the invaluable intelligence Darnavan brings with him from his time walking the halls of this Citadel as one of the Cult.\n\nPlease, take this as a token of this appreciation, and may the Light bolster you as you carve a path through this terrible place.", sourceObjectiveStatus = "unverified-source-field" }
quests[24870] = { id = 24870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Ramparts", description = "As if this place weren't enough of a madhouse to begin with, we're fighting a war on two fronts up here, with the Scourge on one side and those blasted Alliance dogs on our other flank!\n\nWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.\n\nI'll be honest -- he's a bit much for us to handle, but you and your companions look up to the task.", sourceObjective = "Slay the Rotting Frost Giant.", progress = "Is the giant dead?", completion = "The giant is dead? For the Horde!\n\nThe way onward will soon be clear. Take some of these spoils of the battle as a token of our gratitude, and we will drink together in celebration once the Frozen Throne has been ground to dust!", sourceObjectiveStatus = "unverified-source-field" }
quests[24871] = { id = 24871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Ramparts", description = "As if this place weren't enough of a madhouse to begin with, we're fighting a war on two fronts up here, with the Scourge on one side and those blasted Horde dogs on our other flank!\n\nWe are here to clear a safe landing for our vessels, but a behemoth of a giant on the other side of the Ramparts is hurling debris at anything that comes close and keeping our smaller ships at bay.\n\nI'll be honest -- he's a bit much for us to handle, but you and your companions look up to the task.", sourceObjective = "Slay the Rotting Frost Giant.", progress = "Is the giant dead?", completion = "The giant is dead? Praise the Light!\n\nThe way onward and upward is clear. Take some of these spoils of the battle as a token of our gratitude, and we will drink together in celebration once the Frozen Throne has been ground to dust!", sourceObjectiveStatus = "unverified-source-field" }
quests[24872] = { id = 24872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respite for a Tormented Soul", description = "Take this Life Crystal, and have your companions take one as well. It contains potent energies from the verdant Dragonshrine in Dragonblight, and it was my own secret to resisting the dark magics of this place for so long.\n\nWhen you face Sindragosa, battle her until she is weakened, and then have your companions use these Crystals to coax out the essence that is dormant within her. If you then defeat her, you should be able to recover it and return it to Wyrmrest Temple in Dragonblight.", sourceObjective = "Use the Life Crystals to preserve Sindragosa's Essence.", progress = "What do you hold there in your hands, mortal?", completion = "<Kalecgos sighs>\n\nSo much suffering, so much needless destruction. These have not been kind times for my brothers and sisters. But thanks to your efforts, brave adventurers, this darkened yet still noble soul may find peace at last.\n\nRest now, Sindragosa. You are home....", sourceObjectiveStatus = "unverified-source-field" }
quests[24873] = { id = 24873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Residue Rendezvous", description = "Professor Putricide has been holed up in his foul laboratory, experimenting and refining increasingly lethal strains of blight to be used against us. If only we could obtain pure samples of the toxins, our researchers could concoct an antidote that would save countless lives.\n\nBut there's a catch -- a proper sample will need to mix two active strains within a living host. Should you have the... misfortune... of becoming such a host, please return here immediately so that we can harvest you for study.", sourceObjective = "Return to Alchemist Adrianna while infected with Orange and Green Blight.", progress = "Putricide's Blight is one of the Scourge's most powerful weapons against us.", completion = "At last, we have live specimens to study! You have helped to save countless lives this day, {name}.\n\nPlease, take this as a token of thanks for this great deed.", sourceObjectiveStatus = "unverified-source-field" }
quests[24874] = { id = 24874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Quickening", description = "These Scourge bloodsuckers -- San'layn they call themselves - give me the creeps. We've had one of our best men keeping an eye on them. But this morning he got sloppy and got himself taken prisoner. He's being interrogated by the Queen herself right now, and his cries echo through the Crimson Halls. Please, save him before it's too late!", sourceObjective = "Rescue Infiltrator Minchar before he is executed.", completion = "Whew, I thought I was a goner! I heard talk of a resurrection ritual going on in these Halls and went in for a closer look, but one of those blasted vampires sniffed me out. They strung me up here, draining my life energy and hoping I'd break and divulge our plans of attack. As if I even know what Tirion has planned!\n\nPlease, take these spoils of war as a small token of gratitude for saving my life.", sourceObjectiveStatus = "unverified-source-field" }
quests[24875] = { id = 24875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deprogramming", description = "We had hoped to place a man on the inside of the Cult of the Damned, to give us an inside angle on the Lich King's machinations, but we... underestimated the persuasive powers of Arthas and his dark minister, Lady Deathwhisper.\n\nOur man, Darnavan, is one of them now.\n\nIf you plan on fighting your way through the Oratory ahead, please keep your eyes peeled for Darnavan. If you can bring him back to us alive, we can attempt to reverse the Cult's brainwashing.", sourceObjective = "Defeat Lady Deathwhisper while ensuring that Darnavan survives.", progress = "Darnavan has been among the Cult for so long now that there is no telling how he will react. He is a well-trained warrior, so be on your guard!", completion = "Thank you, {name}!\n\nI owe you a debt of gratitude for rescuing a friend whom I had thought forever lost to the clutches of the Cult. And the Argent Crusade owes you a debt for the invaluable intelligence Darnavan brings with him from his time walking the halls of this Citadel as one of the Cult.\n\nPlease, take this as a token of this appreciation, and may the Light bolster you as you carve a path through this terrible place.", sourceObjectiveStatus = "unverified-source-field" }
