quests[24914] = { id = 24914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personal Property", description = "You can detect no hinges or openings on this box. Were it not for the shifting of items inside, it could easily be mistaken for solid metal.\n\nIf anyone could know the method of its opening, it would be Highlord Mograine.", sourceObjective = "Bring the Sealed Chest to Highlord Darion Mograine in Icecrown Citadel.\n\nProvided item:", sourceObjectiveStatus = "unverified-source-field" }
