quests[25306] = { id = 25306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You're In The Army Gnow!" }
quests[25444] = { id = 25444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Perfect Spies", description = "Now, it would be foolish to go in blind 'ere, so I be creatin' some tiny spies to gather information for Vol'jin. He got to know what's goin' on over on de islands.\n\nI could use da help, if you be feelin' up to it. I tell ya how it's done. First, ya gotta catch de frogs. Dey like to stay in de shade of da palm trees around Sen'jin.\n\nOnce ya have de frogs, bring 'em over here to my sentry totem an' attune dem to me sight.", sourceObjective = "Capture 5 Sen'jin Frogs and attune them to Vanira's sight at her Sentry Totem.", sourceObjectiveStatus = "unverified-source-field" }
quests[25482] = { id = 25482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Headless Horseman" }
quests[25483] = { id = 25483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Coren Direbrew" }
quests[25484] = { id = 25484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Ahune" }
quests[25485] = { id = 25485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Hummel" }
quests[26012] = { id = 26012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at Wyrmrest", description = "My old friend Krasus sends word of dire happenings at Wyrmrest, in Dragonblight. His missive was brief, but it seems that there has been some sort of attack on the Ruby Sanctum beneath the Temple.\n\nPressing business here in Dalaran keeps me from attending to the matter personally, but I have heard word of your exploits in the Lich King's Citadel and you are doubtless up to the task -- perhaps you could assist Krasus in my stead?", sourceObjective = "Speak with Krasus at Wyrmrest Temple in Dragonblight.", sourceObjectiveStatus = "unverified-source-field" }
quests[26013] = { id = 26013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Sanctum", description = "{race}, something terrible has transpired within the Ruby Sanctum beneath the Temple.\n\nThe entry to the Sanctum is in ruins, and its guardians violently slain. We sent scouts to investigate, but they have not returned. I cannot help but fear the worst.\n\nEnter the Ruby Sanctum and discover what has befallen the home of my flight. Once we have more information, we can plan our next steps accordingly.", sourceObjective = "Investigate the Ruby Sanctum beneath Wyrmrest Temple.", sourceObjectiveStatus = "unverified-source-field" }
quests[26034] = { id = 26034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Destroyer", description = "This was no reckless attack, but rather a carefully orchestrated strike against the heart of the Red Dragonflight.\n\nZarithrian, on the bluff over there, is overseeing the assault, but the true leader of this force is a brash and powerful Twilight dragon named Halion. Not since Dargonax has a full-grown spawn of Sinestra's twisted experiments been seen.\n\nSlay him, {name}, and then when the invasion has been fully repelled, report to Krasus regarding all you have seen here.", sourceObjective = "Defeat Halion and repel the invasion of the Ruby Sanctum.", sourceObjectiveStatus = "unverified-source-field" }
quests[60860] = { id = 60860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Reward has Arrived!" }
quests[63448] = { id = 63448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deluxe Delivery", sourceObjective = "Greetings {name}, I've been expecting you. An acquaintance of mine asked me to give you these items when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose an item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[63450] = { id = 63450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deluxe Delivery", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have these rewards in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose any of these items, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[63767] = { id = 63767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imp in a Ball", sourceObjective = "Greetings {class}, I've been expecting you. An acquaintance of mine asked me to give you something when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose this item, you can find him on the docks in Booty Bay to get a replacement.", sourceObjectiveStatus = "unverified-source-field" }
quests[63768] = { id = 63768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imp in a Ball", sourceObjective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have this reward in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose this item, come back and I'll give you a replacement, no charge.", sourceObjectiveStatus = "unverified-source-field" }
quests[63770] = { id = 63770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Thanks", sourceObjective = "Greetings {name},\n\nWe have a special gift of appreciation for being a passionate collector! We would like to present you with this small yet feisty friend.  May he lead you to new adventures through the Dark Portal and into Outland!", sourceObjectiveStatus = "unverified-source-field" }
quests[63865] = { id = 63865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Special Thanks", sourceObjective = "Greetings {name},\n\nWe have a special gift of appreciation for being a passionate collector! We would like to present you with this small yet feisty friend.  May he lead you to new adventures through the Dark Portal and into Outland!", sourceObjectiveStatus = "unverified-source-field" }
